public sealed class MutationGate {public SemaphoreSlim Lock{get;}=new(1,1);}
public sealed class MutationFilter(MutationGate gate):IEndpointFilter {
 public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context,EndpointFilterDelegate next){if(context.HttpContext.Request.Method is "GET" or "HEAD" or "OPTIONS")return await next(context);await gate.Lock.WaitAsync(context.HttpContext.RequestAborted);try{var db=context.HttpContext.RequestServices.GetRequiredService<WholesaleDb>();await using var transaction=await db.Database.BeginTransactionAsync(context.HttpContext.RequestAborted);var result=await next(context);await transaction.CommitAsync(context.HttpContext.RequestAborted);await context.HttpContext.RequestServices.GetRequiredService<RealtimeChanges>().Publish(context.HttpContext.RequestServices.GetRequiredService<IHubContext<CommerceHub>>(),db,context.HttpContext.RequestServices.GetRequiredService<ILogger<MutationFilter>>());return result;}finally{gate.Lock.Release();}}
}
